// Sotorko service worker — hand-written, not generated by a plugin.
//
// Scope, deliberately: this makes the app INSTALLABLE and gives a real,
// honest fallback screen when there's no connection. It does NOT pretend
// Sotorko works fully offline — the map and report form both depend on
// live Supabase data, and faking offline-first here would mean either
// silently showing stale/wrong safety data or lying about what "offline"
// means for a product like this. See PROJECT_CONTEXT.md V2 notes.
//
// Strategy:
//   - App shell (the pages themselves) + static assets: cache-first after
//     first successful load, so repeat opens are fast even on a slow
//     connection.
//   - Everything under /api/: always network, never cached — this is live
//     safety data, serving a stale cached response here would be actively
//     misleading, not just unhelpful.
//   - Navigation requests that fail entirely (no network, cache miss):
//     fall back to /offline, an honest static page, never a blank tab or a
//     silently stale map.

const CACHE_NAME = "sotorko-shell-v2"; // bumped: push handlers added in Phase 4

// Bump CACHE_NAME (v1 -> v2, etc.) on any deploy that changes these paths
// or their content in a way that matters — the browser won't otherwise know
// to drop the old cache.
const APP_SHELL = [
  "/",
  "/map",
  "/report",
  "/about",
  "/offline",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(APP_SHELL))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key !== CACHE_NAME)
            .map((key) => caches.delete(key))
        )
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Never cache API calls — always hit the network. Live report/map data
  // must never be served stale from a cache.
  if (url.pathname.startsWith("/api/")) {
    return;
  }

  // Only handle same-origin GET requests below this point.
  if (request.method !== "GET" || url.origin !== self.location.origin) {
    return;
  }

  // Navigations (actual page loads, e.g. opening the installed app):
  // try the network first for freshness, fall back to cache, and if
  // both fail, show the honest offline page rather than a browser error.
  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const clone = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, clone));
          return response;
        })
        .catch(
          () =>
            caches.match(request).then((cached) => cached) ||
            caches.match("/offline")
        )
    );
    return;
  }

  // Static assets (JS/CSS/images/fonts): cache-first, network fallback.
  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request).then((response) => {
        if (response.ok) {
          const clone = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, clone));
        }
        return response;
      });
    })
  );
});

// ============================================================================
// Push notifications (Phase 4)
//
// CRITICAL for iOS: every push received here MUST result in a call to
// showNotification, always, inside event.waitUntil. iOS Safari silently
// unsubscribes a device after it observes several "silent" pushes (a push
// delivered without a visible notification shown). There is no
// conditional path in this handler that skips showNotification — if that
// ever changes, iOS subscriptions will start silently dying.
// ============================================================================
self.addEventListener("push", (event) => {
  let payload = { title: "Sotorko", body: "" };
  try {
    if (event.data) payload = event.data.json();
  } catch {
    // Malformed payload — still show a generic notification rather than
    // silently dropping it (see iOS note above).
  }

  event.waitUntil(
    self.registration.showNotification(payload.title || "Sotorko", {
      body: payload.body || "",
      icon: "/icons/icon-192.png",
      badge: "/icons/icon-192.png",
      data: { url: payload.url || "/map" },
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification.data?.url || "/map";
  event.waitUntil(
    self.clients
      .matchAll({ type: "window", includeUncontrolled: true })
      .then((clientList) => {
        for (const client of clientList) {
          if (client.url.includes(new URL(url, self.location.origin).pathname) && "focus" in client) {
            return client.focus();
          }
        }
        if (self.clients.openWindow) {
          return self.clients.openWindow(url);
        }
      })
  );
});
